import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_upper_triangular_matmul(
    torch::Tensor A,
    torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

namespace cute_upper_triangular_matmul_detail {

constexpr int TILE = 32;
constexpr int WARPS_X = 2;
constexpr int WARPS_Y = 2;
constexpr int WARP_M = 16;
constexpr int WARP_N = 16;
constexpr int THREADS = 32 * WARPS_X * WARPS_Y;
__global__ void cute_upper_triangular_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N)
{
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];
    const int tid = threadIdx.x;
    const int warp_id = tid >> 5;
    const int lane = tid & 31;
    const int warp_tile_y = warp_id / WARPS_X;
    const int warp_tile_x = warp_id % WARPS_X;
    const int lane_row = lane / 4;
    const int lane_col = (lane % 4) * 4;
    const int row_base = blockIdx.y * TILE + warp_tile_y * WARP_M + lane_row;
    const int col_base = blockIdx.x * TILE + warp_tile_x * WARP_N + lane_col;
    auto gA = make_tensor(
        make_gmem_ptr(A),
        make_shape(N, N),
        make_stride(N, Int<1>{}));
    auto gB = make_tensor(
        make_gmem_ptr(B),
        make_shape(N, N),
        make_stride(N, Int<1>{}));
    auto gC = make_tensor(
        make_gmem_ptr(C),
        make_shape(N, N),
        make_stride(N, Int<1>{}));
    auto sA = make_tensor(
        make_smem_ptr(&As[0][0]),
        make_shape(Int<TILE>{}, Int<TILE>{}),
        make_stride(Int<TILE>{}, Int<1>{}));
    auto sB = make_tensor(
        make_smem_ptr(&Bs[0][0]),
        make_shape(Int<TILE>{}, Int<TILE>{}),
        make_stride(Int<TILE>{}, Int<1>{}));
    float acc[2][4] = {};
    for (int k0 = 0; k0 < N; k0 += TILE) {
        if ((N & 3) == 0) {
            for (int idx = tid * 4; idx < TILE * TILE; idx += THREADS * 4) {
                const int tile_row = idx / TILE;
                const int tile_col = idx % TILE;
                const int global_row = blockIdx.y * TILE + tile_row;
                const int global_col = k0 + tile_col;
                if (global_row < N && global_col + 3 < N) {
                    *reinterpret_cast<float4*>(&As[tile_row][tile_col]) =
                        *reinterpret_cast<const float4*>(A + global_row * N + global_col);
                } else {
                    #pragma unroll
                    for (int v = 0; v < 4; ++v) {
                        const int col = global_col + v;
                        As[tile_row][tile_col + v] =
                            (global_row < N && col < N) ?
                                gA(global_row, col) : 0.0f;
                    }
                }
                const int b_global_row = k0 + tile_row;
                const int b_global_col = blockIdx.x * TILE + tile_col;
                if (b_global_row < N && b_global_col + 3 < N) {
                    *reinterpret_cast<float4*>(&Bs[tile_row][tile_col]) =
                        *reinterpret_cast<const float4*>(B + b_global_row * N + b_global_col);
                } else {
                    #pragma unroll
                    for (int v = 0; v < 4; ++v) {
                        const int col = b_global_col + v;
                        Bs[tile_row][tile_col + v] =
                            (b_global_row < N && col < N) ?
                                gB(b_global_row, col) : 0.0f;
                    }
                }
            }
        } else {
            for (int idx = tid; idx < TILE * TILE; idx += THREADS) {
                const int tile_row = idx / TILE;
                const int tile_col = idx % TILE;
                const int global_row = blockIdx.y * TILE + tile_row;
                const int global_col = k0 + tile_col;
                sA(tile_row, tile_col) =
                    (global_row < N && global_col < N) ?
                        gA(global_row, global_col) : 0.0f;
                const int b_global_row = k0 + tile_row;
                const int b_global_col = blockIdx.x * TILE + tile_col;
                sB(tile_row, tile_col) =
                    (b_global_row < N && b_global_col < N) ?
                        gB(b_global_row, b_global_col) : 0.0f;
            }
        }
        __syncthreads();
        #pragma unroll
        for (int kk = 0; kk < TILE; ++kk) {
            const int global_k = k0 + kk;
            if (global_k < N) {
                #pragma unroll
                for (int r = 0; r < 2; ++r) {
                    const int row = row_base + r * (WARP_M / 2);
                    #pragma unroll
                    for (int c = 0; c < 4; ++c) {
                        const int col = col_base + c;
                        if (row < N && col < N && row <= col &&
                            global_k >= row && global_k <= col) {
                            acc[r][c] +=
                                sA(warp_tile_y * WARP_M +
                                   lane_row + r * (WARP_M / 2),
                                   kk) *
                                sB(kk,
                                   warp_tile_x * WARP_N +
                                   lane_col + c);
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int r = 0; r < 2; ++r) {
        const int row = row_base + r * (WARP_M / 2);
        #pragma unroll
        for (int c = 0; c < 4; ++c) {
            const int col = col_base + c;
            if (row < N && col < N) {
                gC(row, col) = (row <= col) ? acc[r][c] : 0.0f;
            }
        }
    }
}

} // namespace cute_upper_triangular_matmul_detail

torch::Tensor cute_upper_triangular_matmul(
    torch::Tensor A,
    torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must have dtype float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must have dtype float32");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.size(1) == B.size(0), "A and B dimensions must match");

    const int N = static_cast<int>(A.size(0));

    auto A_contiguous = A.contiguous();
    auto B_contiguous = B.contiguous();
    auto C = torch::empty_like(A_contiguous);

    dim3 block(128);
    dim3 grid(
        (N + cute_upper_triangular_matmul_detail::TILE - 1) /
            cute_upper_triangular_matmul_detail::TILE,
        (N + cute_upper_triangular_matmul_detail::TILE - 1) /
            cute_upper_triangular_matmul_detail::TILE);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_upper_triangular_matmul_detail::cute_upper_triangular_matmul_kernel<<<grid, block, 0, stream>>>(
        A_contiguous.data_ptr<float>(),
        B_contiguous.data_ptr<float>(),
        C.data_ptr<float>(),
        N);
    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CuTE upper-triangular matmul kernel launch failed");

    return C;
}
"""

cute_ext = load_inline(
    name="cute_upper_triangular_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_upper_triangular_matmul"],
    extra_cflags=[
        "-O3",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_upper_triangular_matmul(A, B)

